/**
 * Session Cost Tracker
 *
 * Tracks costs across a session with limits and warnings.
 */

import type {
  TokenUsage,
  CostResult,
  SessionCostData,
  CostEvent,
  CostTrackerConfig,
  CostStore,
} from './types';
import { calculateCost } from './calculator';

/**
 * In-memory cost store
 */
export class InMemoryCostStore implements CostStore {
  private sessions = new Map<string, SessionCostData>();

  async get(sessionId: string): Promise<SessionCostData | null> {
    return this.sessions.get(sessionId) ?? null;
  }

  async set(sessionId: string, data: SessionCostData): Promise<void> {
    this.sessions.set(sessionId, data);
  }

  async delete(sessionId: string): Promise<void> {
    this.sessions.delete(sessionId);
  }

  async listByUser(userId: string): Promise<SessionCostData[]> {
    return Array.from(this.sessions.values()).filter(s => s.userId === userId);
  }
}

/**
 * Create a session cost tracker
 */
export function createCostTracker(config?: CostTrackerConfig) {
  const store = config?.store ?? new InMemoryCostStore();
  const defaultLimit = config?.defaultCostLimit;
  const warningThreshold = config?.warningThreshold ?? 0.8;

  /**
   * Get or create session data
   */
  async function getOrCreateSession(
    sessionId: string,
    userId?: string
  ): Promise<SessionCostData> {
    let session = await store.get(sessionId);

    if (!session) {
      session = {
        sessionId,
        userId,
        totalCost: 0,
        totalInputTokens: 0,
        totalOutputTokens: 0,
        requestCount: 0,
        costByModel: {},
        startedAt: Date.now(),
        updatedAt: Date.now(),
        costLimit: defaultLimit,
        warningThreshold: defaultLimit ? defaultLimit * warningThreshold : undefined,
      };
      await store.set(sessionId, session);
    }

    return session;
  }

  return {
    /**
     * Track a request's cost
     */
    async track(
      sessionId: string,
      model: string,
      usage: TokenUsage,
      options?: { userId?: string; metadata?: Record<string, unknown> }
    ): Promise<{
      cost: CostResult;
      session: SessionCostData;
      limitExceeded: boolean;
      warningTriggered: boolean;
    }> {
      // Calculate cost with any overrides
      const pricingOverride = config?.pricingOverrides?.[model];
      const cost = calculateCost(model, usage, pricingOverride);

      // Get or create session
      const session = await getOrCreateSession(sessionId, options?.userId);

      // Update session
      session.totalCost += cost.totalCost;
      session.totalInputTokens += usage.inputTokens;
      session.totalOutputTokens += usage.outputTokens;
      session.requestCount++;
      session.costByModel[model] = (session.costByModel[model] ?? 0) + cost.totalCost;
      session.updatedAt = Date.now();

      await store.set(sessionId, session);

      // Create event
      const event: CostEvent = {
        timestamp: Date.now(),
        sessionId,
        model,
        usage,
        cost,
        metadata: options?.metadata,
      };

      // Check limits
      let limitExceeded = false;
      let warningTriggered = false;

      if (session.costLimit && session.totalCost >= session.costLimit) {
        limitExceeded = true;
        config?.onLimitExceeded?.(session, event);
      } else if (session.warningThreshold && session.totalCost >= session.warningThreshold) {
        warningTriggered = true;
        config?.onWarning?.(session, event);
      }

      return { cost, session, limitExceeded, warningTriggered };
    },

    /**
     * Get session cost data
     */
    async getSession(sessionId: string): Promise<SessionCostData | null> {
      return store.get(sessionId);
    },

    /**
     * Set cost limit for a session
     */
    async setLimit(
      sessionId: string,
      limit: number,
      options?: { userId?: string }
    ): Promise<void> {
      const session = await getOrCreateSession(sessionId, options?.userId);
      session.costLimit = limit;
      session.warningThreshold = limit * warningThreshold;
      await store.set(sessionId, session);
    },

    /**
     * Check if session is within budget
     */
    async checkBudget(sessionId: string): Promise<{
      withinBudget: boolean;
      remaining: number | null;
      used: number;
      limit: number | null;
      percentUsed: number | null;
    }> {
      const session = await store.get(sessionId);

      if (!session) {
        return {
          withinBudget: true,
          remaining: null,
          used: 0,
          limit: null,
          percentUsed: null,
        };
      }

      const limit = session.costLimit ?? null;
      const remaining = limit !== null ? Math.max(0, limit - session.totalCost) : null;
      const percentUsed = limit !== null ? (session.totalCost / limit) * 100 : null;

      return {
        withinBudget: limit === null || session.totalCost < limit,
        remaining,
        used: session.totalCost,
        limit,
        percentUsed,
      };
    },

    /**
     * Reset session costs
     */
    async resetSession(sessionId: string): Promise<void> {
      const session = await store.get(sessionId);
      if (session) {
        session.totalCost = 0;
        session.totalInputTokens = 0;
        session.totalOutputTokens = 0;
        session.requestCount = 0;
        session.costByModel = {};
        session.updatedAt = Date.now();
        await store.set(sessionId, session);
      }
    },

    /**
     * Delete session
     */
    async deleteSession(sessionId: string): Promise<void> {
      await store.delete(sessionId);
    },

    /**
     * Get all sessions for a user
     */
    async getUserSessions(userId: string): Promise<SessionCostData[]> {
      return store.listByUser(userId);
    },

    /**
     * Get total cost across all user sessions
     */
    async getUserTotalCost(userId: string): Promise<number> {
      const sessions = await store.listByUser(userId);
      return sessions.reduce((total, s) => total + s.totalCost, 0);
    },

    /**
     * Get the store instance
     */
    getStore(): CostStore {
      return store;
    },
  };
}

/**
 * Create a cost tracker with hooks for SAGE lifecycle
 */
export function createSAGECostTracker(config?: CostTrackerConfig) {
  const tracker = createCostTracker(config);

  return {
    ...tracker,

    /**
     * Create a hook function for afterLLMCall
     */
    createAfterLLMCallHook() {
      return async (
        context: { sessionId: string; userId?: string },
        response: { inputTokens: number; outputTokens: number }
      ) => {
        // This would be integrated with SAGE config
        // Model comes from the config, not the hook
        console.log('[CostTracker] Request tracked:', {
          sessionId: context.sessionId,
          inputTokens: response.inputTokens,
          outputTokens: response.outputTokens,
        });
      };
    },
  };
}
