/**
 * Cost Calculator
 *
 * Calculates costs based on token usage and model pricing.
 */

import type { TokenUsage, CostResult, ModelPricing } from './types';
import { getModelPricing } from './pricing';

/**
 * Calculate cost from token usage
 */
export function calculateCost(
  model: string,
  usage: TokenUsage,
  pricingOverride?: Partial<ModelPricing>
): CostResult {
  // Get pricing
  const basePricing = getModelPricing(model);
  
  if (!basePricing && !pricingOverride) {
    // Unknown model - return zero cost with warning
    console.warn(`[CostCalculator] Unknown model: ${model}. Returning zero cost.`);
    return {
      totalCost: 0,
      inputCost: 0,
      outputCost: 0,
      model,
      usage,
      breakdown: `Unknown model: ${model}`,
    };
  }

  const pricing = {
    inputCostPer1M: 0,
    outputCostPer1M: 0,
    cachedInputCostPer1M: 0,
    ...basePricing,
    ...pricingOverride,
  };

  // Calculate costs (prices are per 1M tokens)
  const inputCost = (usage.inputTokens / 1_000_000) * pricing.inputCostPer1M;
  const outputCost = (usage.outputTokens / 1_000_000) * pricing.outputCostPer1M;
  
  let cachedCost: number | undefined;
  if (usage.cachedInputTokens && pricing.cachedInputCostPer1M) {
    cachedCost = (usage.cachedInputTokens / 1_000_000) * pricing.cachedInputCostPer1M;
  }

  const totalCost = inputCost + outputCost + (cachedCost ?? 0);

  // Build breakdown string
  const parts = [
    `Input: ${usage.inputTokens.toLocaleString()} tokens × $${pricing.inputCostPer1M}/1M = $${inputCost.toFixed(6)}`,
    `Output: ${usage.outputTokens.toLocaleString()} tokens × $${pricing.outputCostPer1M}/1M = $${outputCost.toFixed(6)}`,
  ];

  if (cachedCost !== undefined) {
    parts.push(
      `Cached: ${usage.cachedInputTokens!.toLocaleString()} tokens × $${pricing.cachedInputCostPer1M}/1M = $${cachedCost.toFixed(6)}`
    );
  }

  parts.push(`Total: $${totalCost.toFixed(6)}`);

  return {
    totalCost,
    inputCost,
    outputCost,
    cachedCost,
    model,
    usage,
    breakdown: parts.join('\n'),
  };
}

/**
 * Calculate cost for multiple usages
 */
export function calculateTotalCost(
  usages: Array<{ model: string; usage: TokenUsage }>
): {
  totalCost: number;
  costByModel: Record<string, number>;
  details: CostResult[];
} {
  const details: CostResult[] = [];
  const costByModel: Record<string, number> = {};
  let totalCost = 0;

  for (const { model, usage } of usages) {
    const result = calculateCost(model, usage);
    details.push(result);
    totalCost += result.totalCost;
    costByModel[model] = (costByModel[model] ?? 0) + result.totalCost;
  }

  return { totalCost, costByModel, details };
}

/**
 * Estimate cost before making a request
 */
export function estimateCost(
  model: string,
  estimatedInputTokens: number,
  estimatedOutputTokens: number
): CostResult {
  return calculateCost(model, {
    inputTokens: estimatedInputTokens,
    outputTokens: estimatedOutputTokens,
  });
}

/**
 * Format cost as currency string
 */
export function formatCost(cost: number, currency: string = 'USD'): string {
  if (cost < 0.01) {
    // Show more precision for small amounts
    return `$${cost.toFixed(6)}`;
  }
  
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
    minimumFractionDigits: 2,
    maximumFractionDigits: 4,
  }).format(cost);
}

/**
 * Compare costs between models
 */
export function compareCosts(
  usage: TokenUsage,
  models: string[]
): Array<{ model: string; cost: CostResult; rank: number }> {
  const results = models.map(model => ({
    model,
    cost: calculateCost(model, usage),
  }));

  // Sort by total cost
  results.sort((a, b) => a.cost.totalCost - b.cost.totalCost);

  return results.map((r, index) => ({
    ...r,
    rank: index + 1,
  }));
}

/**
 * Calculate savings from caching
 */
export function calculateCacheSavings(
  model: string,
  cachedTokens: number
): { savings: number; percentage: number } {
  const pricing = getModelPricing(model);
  
  if (!pricing || !pricing.cachedInputCostPer1M) {
    return { savings: 0, percentage: 0 };
  }

  const regularCost = (cachedTokens / 1_000_000) * pricing.inputCostPer1M;
  const cachedCost = (cachedTokens / 1_000_000) * pricing.cachedInputCostPer1M;
  const savings = regularCost - cachedCost;
  const percentage = (savings / regularCost) * 100;

  return { savings, percentage };
}
