/**
 * Pricing registry (mutable at runtime)
 */
let pricingRegistry: Map<string, ModelPricing> = new Map();

// Initialize with defaults
for (const pricing of DEFAULT_PRICING) {
  pricingRegistry.set(pricing.model, pricing);
}

/**
 * Get pricing for a model
 */
export function getModelPricing(model: string): ModelPricing | undefined {
  // Try exact match first
  if (pricingRegistry.has(model)) {
    return pricingRegistry.get(model);
  }

  // Try fuzzy match (partial model name)
  for (const [key, pricing] of pricingRegistry) {
    if (model.includes(key) || key.includes(model)) {
      return pricing;
    }
  }

  // Try matching without version/date suffix
  const baseModel = model.replace(/-\d{8}$/, '').replace(/-latest$/, '');
  if (pricingRegistry.has(baseModel)) {
    return pricingRegistry.get(baseModel);
  }

  return undefined;
}

/**
 * Register a new model pricing or update existing
 */
export function registerModelPricing(pricing: ModelPricing): void {
  pricingRegistry.set(pricing.model, pricing);
}

/**
 * Register multiple model pricings
 */
export function registerModelPricings(pricings: ModelPricing[]): void {
  for (const pricing of pricings) {
    pricingRegistry.set(pricing.model, pricing);
  }
}

/**
 * Set the entire pricing registry (replaces all)
 */
export function setPricingRegistry(pricings: ModelPricing[]): void {
  pricingRegistry = new Map();
  for (const pricing of pricings) {
    pricingRegistry.set(pricing.model, pricing);
  }
}

/**
 * Get all registered pricings
 */
export function getAllPricings(): ModelPricing[] {
  return Array.from(pricingRegistry.values());
}

/**
 * Get pricings by provider
 */
export function getPricingsByProvider(provider: string): ModelPricing[] {
  return Array.from(pricingRegistry.values()).filter(
    p => p.provider?.toLowerCase() === provider.toLowerCase()
  );
}

/**
 * Reset pricing registry to defaults
 */
export function resetPricingRegistry(): void {
  pricingRegistry = new Map();
  for (const pricing of DEFAULT_PRICING) {
    pricingRegistry.set(pricing.model, pricing);
  }
}

/**
 * Check if a model is free
 */
export function isModelFree(model: string): boolean {
  const pricing = getModelPricing(model);
  if (!pricing) return false;
  return pricing.inputCostPer1M === 0 && pricing.outputCostPer1M === 0;
}

/**
 * Get cheapest model for a provider
 */
export function getCheapestModel(provider?: string): ModelPricing | undefined {
  let models = Array.from(pricingRegistry.values());
  
  if (provider) {
    models = models.filter(m => m.provider?.toLowerCase() === provider.toLowerCase());
  }

  if (models.length === 0) return undefined;

  return models.reduce((cheapest, current) => {
    const cheapestAvg = (cheapest.inputCostPer1M + cheapest.outputCostPer1M) / 2;
    const currentAvg = (current.inputCostPer1M + current.outputCostPer1M) / 2;
    return currentAvg < cheapestAvg ? current : cheapest;
  });
}
